PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ccso: <https://w3id.org/hacid/onto/ccso/>

SELECT
    ?experiment ?experiment_label ?scenario
    (COUNT(DISTINCT ?model) AS ?num_models)
    (COUNT(DISTINCT ?simulation) AS ?num_simulations)
WHERE {
    ?experiment a ccso:ClimateModelIntercomparisonExperiment;
        ccso:experimentId ?experiment_id;
        ccso:hasMemberSimulation ?simulation.
    OPTIONAL {
        ?experiment rdfs:label ?experiment_label.
    }
    OPTIONAL {
        ?experiment ccso:refersToScenario ?scenario.
    }
    ?simulation a ccso:SingleSimulation;
        ccso:usesModel ?model.
}
GROUP BY ?experiment ?experiment_label ?scenario
ORDER BY DESC(?num_simulations)

PREFIX top: <https://w3id.org/hacid/onto/top-level/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX data: <https://w3id.org/hacid/onto/data/>

SELECT
    ?var ?var_label ?var_descr
    (COUNT(DISTINCT ?dataset) AS ?num_datasets_using_it)
WHERE {
      ?var a data:Variable;
          top:isMemberOf <https://w3id.org/hacid/data/cs/variables/cf>;
          rdfs:label ?var_label.
      OPTIONAL {
        ?var rdfs:comment ?var_descr.
      }
    OPTIONAL {
        ?dataset data:holdsSpecializationOfVariable* ?var
    }
}
GROUP BY
    ?var ?var_label ?var_descr
ORDER BY DESC(?num_datasets_using_it) ?var

PREFIX top: <https://w3id.org/hacid/onto/top-level/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX data: <https://w3id.org/hacid/onto/data/>
PREFIX cf: <https://w3id.org/hacid/data/cs/variables/cf/>

SELECT
    ?var ?var_label ?var_descr
    (COUNT(DISTINCT ?dataset) AS ?num_datasets_using_it)
WHERE {
    ?var a data:Variable;
          top:isMemberOf <https://w3id.org/hacid/data/cs/variables/mip>;
        data:holdsSpecializationOfVariable* cf:air_temperature;
        rdfs:label ?var_label.
    OPTIONAL {
        ?var rdfs:comment ?var_descr.
    }
    OPTIONAL {
        ?dataset data:holdsSpecializationOfVariable* ?var
    }
}
GROUP BY
    ?var ?var_label ?var_descr
ORDER BY DESC(?num_datasets_using_it) ?var

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX top: <https://w3id.org/hacid/onto/top-level/>
PREFIX data: <https://w3id.org/hacid/onto/data/>
PREFIX sector: <https://w3id.org/hacid/data/cs/climdex/sectors/>

SELECT
    ?index ?index_label ?index_descr ?index_dim ?index_definition ?from_variable
WHERE {
    ?index a data:Variable;
        top:isMemberOf <https://w3id.org/hacid/data/cs/climdex/indices>;
        top:isClassifiedBy sector:Water%20Resources%20and%20Food%20Security;
        rdfs:label ?index_label;
        data:derivedFromVariable ?from_variable.
    OPTIONAL {
        ?index rdfs:comment ?index_descr.
    }
    OPTIONAL {
        ?index data:hasValuesOn ?index_dim.
    }
    OPTIONAL {
        ?index top:definition ?index_definition.
    }
}
ORDER BY ?index

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX top: <https://w3id.org/hacid/onto/top-level/>
PREFIX ccso: <https://w3id.org/hacid/onto/ccso/>

SELECT
    ?hazard ?hazard_label
    (COUNT(DISTINCT ?index) AS ?num_indices)
WHERE {
    ?hazard a ccso:HazardType;
        rdfs:label ?hazard_label.
    OPTIONAL {
        ?hazard top:associatedWith ?index.
        ?index top:isMemberOf <https://w3id.org/hacid/data/cs/indices>.
    }
}
GROUP BY ?hazard ?hazard_label
ORDER BY DESC(?num_indices) ?hazard

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX top: <https://w3id.org/hacid/onto/top-level/>
PREFIX data: <https://w3id.org/hacid/onto/data/>
PREFIX hazard: <https://w3id.org/hacid/data/cs/hazard-types/>

SELECT
    ?catalogue ?index ?index_label ?index_descr
WHERE {
    hazard:AgriculturalDrought top:associatedWith ?index.
    ?index a data:Variable;
        top:isMemberOf ?catalogue;
        rdfs:label ?index_label.
    FILTER(?catalogue != <https://w3id.org/hacid/data/cs/indices>)
    FILTER(STRENDS(STR(?catalogue), "/indices"))
    OPTIONAL {
        ?index rdfs:comment ?index_descr.
    }
}
ORDER BY ?catalogue ?index

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX top: <https://w3id.org/hacid/onto/top-level/>
PREFIX data: <https://w3id.org/hacid/onto/data/>

SELECT
    ?climdex_index ?climdex_label ?equivalent_index ?equivalent_label
WHERE {
    ?climdex_index top:isMemberOf <https://w3id.org/hacid/data/cs/climdex/indices>;
        rdfs:label ?climdex_label;
        data:isEquivalentTo ?equivalent_index.
    ?equivalent_index rdfs:label ?equivalent_label.
}
ORDER BY ?climdex_index ?equivalent_index

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ccso: <https://w3id.org/hacid/onto/ccso/>

SELECT
    ?scenario_type ?scenario ?scenario_label
    (COUNT(DISTINCT ?simulation) AS ?num_simulations)
WHERE {
    ?scenario a ccso:EmissionScenario;
        a ?scenario_type.
    ?scenario_type rdfs:subClassOf ccso:EmissionScenario.
    FILTER(?scenario_type != ccso:EmissionScenario)
    OPTIONAL {
        ?scenario rdfs:label ?scenario_label.
    }
    OPTIONAL {
        ?simulation a ccso:SingleSimulation;
            ccso:refersToScenario ?scenario.
    }
}
GROUP BY ?scenario_type ?scenario ?scenario_label
ORDER BY ?scenario_type ?scenario

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX top: <https://w3id.org/hacid/onto/top-level/>
PREFIX ccso: <https://w3id.org/hacid/onto/ccso/>
PREFIX data: <https://w3id.org/hacid/onto/data/>
PREFIX rcp: <https://w3id.org/hacid/data/cs/scenarios/RCP/>
PREFIX mip: <https://w3id.org/hacid/data/cs/variables/mip/>
PREFIX dimension: <https://w3id.org/hacid/data/cs/dimensions/>

SELECT ?model ?simulation ?output ?geodeticResolution
WHERE {
    ?simulation a ccso:SingleSimulation;
        ccso:refersToScenario rcp:RCP4.5;
        ccso:usesModel ?model;
        data:hasOutput ?output.
    ?output data:holdsSpecializationOfVariable* mip:tas;
        data:dependsOnVariable ?geodeticVariable.
    ?geodeticVariable
        data:holdsSpecializationOfVariable* dimension:geodetic;
        data:hasDiscretization/data:hasResolutionValue ?geodeticResolution.
    FILTER(?geodeticResolution < 0.2)
}
ORDER BY ?model ?simulation ?output

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX top: <https://w3id.org/hacid/onto/top-level/>
PREFIX ccso: <https://w3id.org/hacid/onto/ccso/>
PREFIX data: <https://w3id.org/hacid/onto/data/>
PREFIX mip: <https://w3id.org/hacid/data/cs/variables/mip/>
PREFIX dimension: <https://w3id.org/hacid/data/cs/dimensions/>
PREFIX sim: <https://w3id.org/hacid/data/cs/simulations/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?organization ?regional_model ?downscaling ?geodetic_region
WHERE {
    ?downscaling ccso:isDownscalingOf sim:cmip5.HadGEM2-ES.rcp26.r1i1p1;
        ccso:usesModel ?regional_model;
         data:hasOutput/data:isSpecializedAccordingTo [
            data:isSpecializationOn/data:holdsSpecializationOfVariable* dimension:geodetic;
            data:hasSelectedRegion/geo:asWKT ?geodetic_region
        ].
    ?regional_model ccso:isMaintainedBy ?organization.
}
ORDER BY ?organization ?regional_model ?downscaling

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ccso: <https://w3id.org/hacid/onto/ccso/>

SELECT
    ?global_simulation ?global_model
    ?regional_simulation ?regional_model
    ?local_simulation ?local_model
WHERE {
    ?local_simulation ccso:isDownscalingOf ?regional_simulation;
        ccso:usesModel ?local_model.
    ?regional_simulation ccso:isDownscalingOf ?global_simulation;
        ccso:usesModel ?regional_model.
    ?global_simulation ccso:usesModel ?global_model.
    FILTER NOT EXISTS { ?global_simulation ccso:isDownscalingOf ?any }
}
ORDER BY ?global_simulation ?regional_simulation ?local_simulation

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX top: <https://w3id.org/hacid/onto/top-level/>
PREFIX ccso: <https://w3id.org/hacid/onto/ccso/>
PREFIX data: <https://w3id.org/hacid/onto/data/>
PREFIX domain: <https://w3id.org/hacid/data/cs/cordex/domains/>

SELECT
    ?grid ?resolution
    (COUNT(DISTINCT ?simulation) AS ?num_simulations)
    (COUNT(DISTINCT ?driving_model) AS ?num_driving_models)
    (COUNT(DISTINCT ?regional_model) AS ?num_regional_models)
WHERE {
    domain:EUR top:hasConstituent ?grid.
    OPTIONAL {
        ?grid data:hasDiscretization/data:hasResolutionValue ?resolution.
    }
    ?simulation a ccso:SingleSimulation;
        data:hasOutput/data:dependsOnVariable ?grid;
        ccso:usesModel ?regional_model;
        ccso:isDownscalingOf/ccso:usesModel ?driving_model.
}
GROUP BY ?grid ?resolution
ORDER BY ?resolution ?grid

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX top: <https://w3id.org/hacid/onto/top-level/>

SELECT
    ?parent_operation ?operation ?operation_label ?information_type
WHERE {
    ?operation a top:Operation;
        rdfs:label ?operation_label.
    OPTIONAL {
        ?operation top:specializes ?parent_operation.
        FILTER NOT EXISTS {
            ?operation top:specializes ?intermediate.
            ?intermediate top:specializes ?parent_operation.
            FILTER(?intermediate != ?operation && ?intermediate != ?parent_operation)
        }
    }
    OPTIONAL {
        ?operation top:definesRole/top:hasExpectedType ?information_type.
        FILTER(isIRI(?information_type))
    }
}
ORDER BY ?parent_operation ?operation

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX top: <https://w3id.org/hacid/onto/top-level/>
PREFIX methods: <https://w3id.org/hacid/data/cs/wf/methods/>

SELECT
    ?method ?method_label ?method_alt_label
WHERE {
    ?method a top:Method;
        top:specializes methods:BiasCorrection;
        rdfs:label ?method_label.
    OPTIONAL {
        ?method top:altLabel ?method_alt_label.
    }
}
ORDER BY ?method
